import tkinter as tk
import random
import base64
import io
from PIL import Image, ImageTk

# 猫咪图片base64数据，无需外部文件
CAT_IMG_BASE64 = b""""""

def main():
    # 创建主窗口
    root = tk.Tk()
    root.title("猫咪桌面宠物")
    
    # 窗口基础设置
    root.overrideredirect(True)       # 去掉窗口边框
    root.attributes('-topmost', True) # 窗口始终置顶
    # Windows系统下设置透明色：洋红色(#ff00ff)会被完全透明
    root.attributes('-transparentcolor', '#ff00ff')
    
    # 从base64加载并缩放猫咪图片
    img_data = base64.b64decode(CAT_IMG_BASE64)
    original_img = Image.open(io.BytesIO(img_data))
    # 统一缩放到宽度200像素，高度等比例自适应
    pet_width = 200
    pet_height = int(original_img.height * (pet_width / original_img.width))
    pet_img = original_img.resize((pet_width, pet_height), Image.Resampling.LANCZOS)
    pet_photo = ImageTk.PhotoImage(pet_img)
    
    # 创建画布，背景色设为透明色，无边框
    canvas = tk.Canvas(
        root, 
        width=pet_width, 
        height=pet_height, 
        bg='#ff00ff', 
        highlightthickness=0
    )
    canvas.pack()
    # 在画布上绘制猫咪图片
    canvas.create_image(0, 0, anchor=tk.NW, image=pet_photo)
    
    # -------------------------- 拖动功能 --------------------------
    drag_offset = {"x": 0, "y": 0}
    
    def on_mouse_press(event):
        """鼠标按下时记录偏移量"""
        drag_offset["x"] = event.x
        drag_offset["y"] = event.y
    
    def on_mouse_drag(event):
        """鼠标拖动时更新窗口位置"""
        new_x = root.winfo_x() + event.x - drag_offset["x"]
        new_y = root.winfo_y() + event.y - drag_offset["y"]
        root.geometry(f"+{new_x}+{new_y}")
    
    # 绑定鼠标拖动事件
    canvas.bind("<ButtonPress-1>", on_mouse_press)
    canvas.bind("<B1-Motion>", on_mouse_drag)
    
    # -------------------------- 自动移动功能 --------------------------
    # 随机初始移动方向和速度
    move_speed_x = random.choice([-1, 1]) * random.randint(1, 2)
    move_speed_y = random.choice([-1, 1]) * random.randint(1, 2)
    screen_w = root.winfo_screenwidth()
    screen_h = root.winfo_screenheight()
    
    def auto_walk():
        nonlocal move_speed_x, move_speed_y
        current_x = root.winfo_x()
        current_y = root.winfo_y()
        
        # 计算新位置
        next_x = current_x + move_speed_x
        next_y = current_y + move_speed_y
        
        # 碰到屏幕边缘时反弹
        if next_x <= 0 or next_x + pet_width >= screen_w:
            move_speed_x = -move_speed_x
        if next_y <= 0 or next_y + pet_height >= screen_h:
            move_speed_y = -move_speed_y
        
        # 更新窗口位置
        root.geometry(f"+{next_x}+{next_y}")
        # 每60毫秒移动一次，控制移动速度
        root.after(60, auto_walk)
    
    # 启动自动漫步
    auto_walk()
    
    # -------------------------- 右键菜单 --------------------------
    def on_right_click(event):
        """右键点击弹出菜单"""
        right_menu.post(event.x_root, event.y_root)
    
    def quit_pet():
        """退出宠物程序"""
        root.destroy()
    
    # 创建右键菜单
    right_menu = tk.Menu(root, tearoff=0)
    right_menu.add_command(label="退出宠物", command=quit_pet)
    canvas.bind("<Button-3>", on_right_click)
    
    # 设置初始位置：屏幕右下角，距离边缘50像素
    init_x = screen_w - pet_width - 50
    init_y = screen_h - pet_height - 100
    root.geometry(f"+{init_x}+{init_y}")
    
    # 启动主循环
    root.mainloop()

if __name__ == "__main__":
    main()
